const stats = $input.first().json;

// Format dates
const weekStart = new Date(stats.week_start).toLocaleDateString('fr-FR', { day: 'numeric', month: 'short' });
const weekEnd = new Date(stats.week_end).toLocaleDateString('fr-FR', { day: 'numeric', month: 'short' });

// Calculate engagement rate
const engagementRate = stats.summary.total_learners > 0 
  ? Math.round((stats.summary.active_learners / stats.summary.total_learners) * 100) 
  : 0;

// Format top learners for embed
const topLearnersField = stats.top_learners?.slice(0, 5).map((l, i) => {
  const medals = ['🥇', '🥈', '🥉', '4️⃣', '5️⃣'];
  return `${medals[i]} **${l.display_name}** - ${l.xp_earned} XP`;
}).join('\n') || 'Aucun apprenant actif cette semaine';

// Format course stats
const courseStatsField = stats.course_stats?.slice(0, 3).map(c => {
  return `📖 **${c.course_title}**\n└ ${c.new_enrollments_this_week} inscriptions, ${c.completions_this_week} complétion(s)`;
}).join('\n\n') || 'Aucune activité de cours';

// Build Discord embed
const embed = {
  title: '📊 Rapport Hebdomadaire - Apprentissage',
  description: `Semaine du ${weekStart} au ${weekEnd}`,
  color: 5814783,
  fields: [
    {
      name: '📈 Résumé Global',
      value: `👥 **${stats.summary.total_learners}** apprenants (${stats.summary.active_learners} actifs)\n📚 **${stats.summary.lessons_completed}** leçons complétées\n✅ **${stats.summary.quizzes_passed}** quiz réussis\n🆕 **${stats.summary.new_enrollments}** nouvelles inscriptions\n💫 **${stats.total_xp_earned?.toLocaleString() || 0}** XP distribués`,
      inline: false
    },
    {
      name: '🏆 Top Apprenants',
      value: topLearnersField,
      inline: false
    },
    {
      name: '📖 Cours Populaires',
      value: courseStatsField,
      inline: false
    },
    {
      name: '🎖️ Badges & Engagement',
      value: `🏅 **${stats.badges_awarded || 0}** badges attribués\n📊 Taux d'engagement: **${engagementRate}%**`,
      inline: false
    }
  ],
  footer: {
    text: 'Généré automatiquement par le système d\'apprentissage'
  },
  timestamp: new Date().toISOString()
};

return {
  json: {
    embed: embed,
    summary: stats.summary,
    engagement_rate: engagementRate
  }
};
